// ── Typed variant constructors and accessors ──

func TestBhvUnions001_ComposedSchema_PetFood_TypedConstructorAndAccessorsNameTheVariant(t *testing.T) {
	t.Parallel()
	food := models.NewDryFoodPetFood(*models.NewDryFood(2.5))

	if !food.IsDryFood() || food.IsWetFood() {
		t.Fatal("expected the union to hold a DryFood and not a WetFood")
	}
	dry, ok := food.AsDryFood()
	if !ok || dry.WeightKg != 2.5 {
		t.Errorf("expected the DryFood back, got %+v (ok=%v)", dry, ok)
	}
	if _, ok := food.AsWetFood(); ok {
		t.Error("expected AsWetFood to report false")
	}
	data, err := json.Marshal(food)
	if err != nil {
		t.Fatalf("failed to serialize PetFood: %v", err)
	}
	if string(data) != `{"foodType":"dry","weightKg":2.5}` {
		t.Errorf("unexpected wire form %s", string(data))
	}
}

